const listing = $('Enrich').item.json;
let triage = null;
try {
  const raw = $json.content && $json.content[0] && $json.content[0].text;
  if (raw) triage = JSON.parse(raw);
} catch (e) { triage = null; }

// Deterministic preference weights, applied on top of the LLM's fundamentals-only
// fit_score so ranking reflects fixed user priorities (edit W to re-tune).
// The LLM detects the attributes (needs language understanding); the weights live
// here (predictable, visible via triage.score_adjustments). Kept out of the LLM
// prompt to avoid double-counting.
if (triage && typeof triage.fit_score === 'number') {
  const W = {
    eco: { minergie_eco: 8, minergie_a: 7, minergie_p: 7, minergie: 5, cecb: 2, none: 0 },
    induction: 3,
    noParking: -6,
    nearNature: 4,
    nearTransit: 7,
    nearShops: 2,
  };
  const base = triage.fit_score;
  const adj = [];
  const eco = W.eco[triage.eco_label] || 0;
  if (eco) adj.push(['eco:' + triage.eco_label, eco]);
  if (triage.cooktop === 'induction') adj.push(['induction', W.induction]);
  if (triage.parking === 'no') adj.push(['sans parking', W.noParking]);
  if (triage.near_transit) adj.push(['transports', W.nearTransit]);
  if (triage.near_nature) adj.push(['nature', W.nearNature]);
  if (triage.near_shops) adj.push(['commerces', W.nearShops]);
  const delta = adj.reduce((s, a) => s + a[1], 0);
  triage.fit_score_base = base;
  triage.fit_score = Math.max(0, Math.min(100, Math.round(base + delta)));
  triage.score_adjustments = adj.map(a => a[0] + ' ' + (a[1] > 0 ? '+' : '') + a[1]);
}

return [{ json: { ...listing, triage, fit_score: triage ? triage.fit_score : null } }];

// Adaptive peer-relative price scoring (design: claude-docs/apartment-price-baseline.md).
// Reads the LLM+attribute score from Merge triage and the market baseline from Peer baseline,
// computes an expected rent for THIS flat's class, folds the residual into fit_score, and
// applies an absolute affordability gate. Degrades to a no-op when data is missing.
const l = $('Merge triage').item.json;   // {...listing, triage, fit_score(base+attr weights)}
const b = $('Peer baseline').item.json;  // {anchor, n_global, pool_med_m2, seg_median, n_seg}
const t = l.triage;

const PRICE = {
  BETA: 0.45, REF_M2: 75, DEFAULT_ANCHOR: 23.0, MIN_N: 8,
  K_SHRINK: 6, K_POINTS: 110, PTS_MIN: -18, PTS_MAX: 25,
  MULT_MIN: 0.82, MULT_MAX: 1.28,
  BUDGET_MAX: 2100, HARD_MAX: 2300, GATE_SOFT: 15, GATE_CAP: 45,
  condPrior: { modern: 1.12, new_build: 1.12, renovated: 1.0, old: 0.94, unknown: 1.0 },
  ecoPrior: { minergie: 1.04, cecb: 1.01, none: 1.0 },
};
const num = x => { const n = (x === null || x === undefined || x === '') ? NaN : Number(x); return isNaN(n) ? null : n; };

if (t && typeof t.fit_score === 'number') {
  const rent = num(l.rent_gross) ?? num(l.rent_net);
  const m2 = num(l.m2);
  const nGlobal = num(b && b.n_global) || 0;
  const anchorLive = num(b && b.anchor);
  const anchor = (nGlobal >= PRICE.MIN_N && anchorLive) ? anchorLive : PRICE.DEFAULT_ANCHOR;

  const ecoKey = (t.eco_label && String(t.eco_label).indexOf('minergie') === 0) ? 'minergie' : (t.eco_label || 'none');
  const priorRatio = (PRICE.condPrior[t.condition] ?? 1.0) * (PRICE.ecoPrior[ecoKey] ?? 1.0);
  const nSeg = num(b && b.n_seg) || 0;
  const segMed = num(b && b.seg_median);
  let mult = priorRatio;
  if (nSeg > 0 && segMed && anchor) {
    const obsRatio = segMed / anchor;
    mult = (nSeg * obsRatio + PRICE.K_SHRINK * priorRatio) / (nSeg + PRICE.K_SHRINK);
  }
  mult = Math.max(PRICE.MULT_MIN, Math.min(PRICE.MULT_MAX, mult));

  let pricePoints = 0, expected = null, residualPct = null, source;
  if (rent && m2 && anchor) {
    const sizeAdj = Math.pow(PRICE.REF_M2 / m2, PRICE.BETA);
    expected = anchor * sizeAdj * mult * m2;
    residualPct = (expected - rent) / expected;                 // + = cheaper than peers
    pricePoints = Math.max(PRICE.PTS_MIN, Math.min(PRICE.PTS_MAX, Math.round(residualPct * PRICE.K_POINTS)));
    source = (nGlobal >= PRICE.MIN_N) ? (nSeg > 0 ? (nSeg >= PRICE.K_SHRINK ? 'data' : 'blend') : 'prior') : 'default-anchor';
  } else {
    source = !rent ? 'no-price' : 'no-size';
  }

  // Reserve the top PTS_MAX points of the 0-100 scale for the price/deal signal: cap the
  // quality contribution (LLM fundamentals + attribute weights) at 100-PTS_MAX so a fully
  // equipped listing can't saturate at 100 before price discriminates a bargain from at-market.
  let score = Math.min(t.fit_score, 100 - PRICE.PTS_MAX) + pricePoints;

  // absolute affordability gate (uses rent alone; applies even when m2 missing)
  let gateNote = null;
  if (rent) {
    if (rent > PRICE.HARD_MAX) { score = Math.min(score, PRICE.GATE_CAP); gateNote = 'hors budget'; }
    else if (rent > PRICE.BUDGET_MAX) {
      const over = (rent - PRICE.BUDGET_MAX) / (PRICE.HARD_MAX - PRICE.BUDGET_MAX);
      score -= Math.round(over * PRICE.GATE_SOFT);
      gateNote = 'au-dessus budget';
    }
  }
  score = Math.max(0, Math.min(100, Math.round(score)));

  const vsPeers = residualPct === null ? null : Math.round(-residualPct * 1000) / 10;  // <0 = cheaper
  t.price_anchor = anchor ? Math.round(anchor * 10) / 10 : null;
  t.price_size_adj = (rent && m2) ? Math.round(Math.pow(PRICE.REF_M2 / m2, PRICE.BETA) * 100) / 100 : null;
  t.price_seg_mult = Math.round(mult * 1000) / 1000;
  t.price_n_seg = nSeg;
  t.price_n_global = nGlobal;
  t.price_expected = expected ? Math.round(expected) : null;
  t.price_vs_peers_pct = vsPeers;
  t.price_points = pricePoints;
  t.price_source = source;

  if (!Array.isArray(t.score_adjustments)) t.score_adjustments = [];
  if (pricePoints !== 0 && vsPeers !== null) {
    t.score_adjustments.push('prix ' + (vsPeers > 0 ? '+' : '') + vsPeers + '% vs pairs ' + (pricePoints > 0 ? '+' : '') + pricePoints);
  }
  if (gateNote) t.score_adjustments.push(gateNote);
  t.fit_score = score;
}

return { json: { ...l, triage: t, fit_score: t ? t.fit_score : (l.fit_score ?? null) } };

