={{ (() => {
const l = $('Price adjust').item.json;
const t = l.triage;
const score = (t && typeof t.fit_score === 'number') ? t.fit_score : 50;
const prio = score >= 80 ? 5 : score >= 60 ? 4 : 3;
const rent = l.rent_gross ?? l.rent_net;
const TIER = { cheap: { lbl: 'bon prix', emo: '💚' }, market: { lbl: 'dans le marché', emo: '🟡' }, expensive: { lbl: 'cher', emo: '🔴' } };
const COND = { old: 'ancien', renovated: 'rénové', modern: 'moderne', new_build: 'neuf' };
const STD = { basic: 'standing simple', standard: 'standing normal', luxury: 'haut standing' };
const ECO = { minergie: 'Minergie', minergie_p: 'Minergie-P', minergie_a: 'Minergie-A', minergie_eco: 'Minergie-ECO', cecb: 'CECB' };
const pv = (p) => (typeof p !== 'number') ? null : (p <= -1 ? (-p) + '% sous le marché comparable' : (p >= 1 ? '+' + p + '% au-dessus du marché' : 'dans le marché'));
const L = [];
L.push((l.rooms ? l.rooms + ' pièces' : '? pièces') + (l.m2 ? ' · ' + l.m2 + ' m²' : '') + (rent ? ' · CHF ' + rent + '/mois' : '') + (l.commune ? ' · ' + l.commune : ''));
if (t) {
  const tier = TIER[t.price_tier];
  const v = ['★ ' + score + '/100'];
  if (tier) v.push(tier.emo + ' ' + tier.lbl);
  const d = pv(t.price_vs_peers_pct);
  if (d) v.push(d);
  L.push(v.join(' · '));
  const q = [];
  if (COND[t.condition]) q.push(COND[t.condition]);
  if (STD[t.standard]) q.push(STD[t.standard]);
  if (ECO[t.eco_label]) q.push('🌿 ' + ECO[t.eco_label]);
  if (q.length) L.push(q.join(' · '));
  if (t.summary_fr) L.push(t.summary_fr);
  const tg = [];
  if (t.cooktop === 'induction') tg.push('🔥 plaques induction');
  if (t.near_transit) tg.push('🚆 transports');
  if (t.near_nature) tg.push('🌳 nature');
  if (t.near_shops) tg.push('🛒 commerces');
  if (t.parking === 'no') tg.push('🚫 sans parking');
  if (tg.length) L.push(tg.join(' · '));
  if (t.price_expected) L.push('⚖️ attendu ~CHF ' + t.price_expected + (t.price_n_seg ? ' (' + t.price_n_seg + ' biens comparés)' : ''));
}
const feats = l.features ? Object.entries({ balcon: l.features.balcony, ascenseur: l.features.elevator, parking: l.features.parking, 'lave-linge': l.features.washingMachine, minergie: l.features.minergie, animaux: l.features.pets }).filter(e => e[1]).map(e => e[0]) : [];
if (feats.length) L.push('✓ ' + feats.join(' · '));
if (l.agency) L.push('🏢 ' + l.agency + (l.agency_reputation ? ' — ' + l.agency_reputation : ''));
L.push('via ' + l.source);
const tags = ['house'];
if (score >= 80) tags.push('loudspeaker');
return JSON.stringify({ topic: 'homelab-appart', title: l.title, message: L.join('\n'), click: l.url, priority: prio, tags });
})() }}

parameters.jsCode:
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const l = $('Price adjust').item.json;
const t = l.triage;
const score = (t && typeof t.fit_score === 'number') ? t.fit_score : 50;
const rent = l.rent_gross ?? l.rent_net;

// --- enum -> French label maps (schema values come back in English) ---
const TIER = { cheap: { lbl: 'bon prix', emo: '\u{1F49A}' }, market: { lbl: 'dans le marché', emo: '\u{1F7E1}' }, expensive: { lbl: 'cher', emo: '\u{1F534}' } };
const COND = { old: 'ancien', renovated: 'rénové', modern: 'moderne', new_build: 'neuf' };
const STD = { basic: 'standing simple', standard: 'standing normal', luxury: 'haut standing' };
const ECO = { minergie: 'Minergie', minergie_p: 'Minergie-P', minergie_a: 'Minergie-A', minergie_eco: 'Minergie-ECO', cecb: 'CECB' };

// price verdict vs comparable listings, in plain French
const priceVerdict = (pct) => {
  if (typeof pct !== 'number') return null;
  if (pct <= -1) return (-pct) + '% sous le marché comparable';
  if (pct >= 1) return '+' + pct + '% au-dessus du marché';
  return 'dans le marché';
};

// ---- core (always shown, kept short & scannable) ----
const core = [];
core.push((score >= 80 ? '\u{1F4E2} ' : '\u{1F3E0} ') + '<b>' + esc(l.title) + '</b>');
core.push(
  (l.rooms ? l.rooms + ' pièces' : '? pièces') +
  (l.m2 ? ' · ' + l.m2 + ' m²' : '') +
  (rent ? ' · CHF ' + rent + '/mois' : '') +
  (l.commune ? ' · ' + esc(l.commune) : '')
);
// verdict line: score + price tier + market delta
const tier = t && TIER[t.price_tier];
const verdict = ['★ ' + score + '/100'];
if (tier) verdict.push(tier.emo + ' ' + tier.lbl);
const pv = t && priceVerdict(t.price_vs_peers_pct);
if (pv) verdict.push(pv);
core.push(verdict.join(' · '));

// ---- detail (folded into an expandable blockquote, ordered by importance) ----
const detail = [];
if (t) {
  // condition / standard / eco on one line
  const qual = [];
  if (t.condition && COND[t.condition]) qual.push(COND[t.condition]);
  if (t.standard && STD[t.standard]) qual.push(STD[t.standard]);
  if (t.eco_label && ECO[t.eco_label]) qual.push('\u{1F33F} ' + ECO[t.eco_label]);
  if (qual.length) detail.push(qual.join(' · '));

  if (t.summary_fr) detail.push(esc(String(t.summary_fr).slice(0, 300)));

  // location / kitchen tags
  const tags = [];
  if (t.cooktop === 'induction') tags.push('\u{1F525} plaques induction');
  if (t.near_transit) tags.push('\u{1F686} transports');
  if (t.near_nature) tags.push('\u{1F333} nature');
  if (t.near_shops) tags.push('\u{1F6D2} commerces');
  if (t.parking === 'no') tags.push('\u{1F6AB} sans parking');
  if (tags.length) detail.push(tags.join(' · '));

  // hard features
  const feats = l.features ? Object.entries({ balcon: l.features.balcony, ascenseur: l.features.elevator, parking: l.features.parking, 'lave-linge': l.features.washingMachine, minergie: l.features.minergie, animaux: l.features.pets }).filter(e => e[1]).map(e => e[0]) : [];
  if (feats.length) detail.push('✓ ' + feats.join(' · '));

  if (l.agency) detail.push('\u{1F3E2} ' + esc(l.agency) + (l.agency_reputation ? ' — ' + esc(l.agency_reputation) : ''));

  // scoring rationale last (least important, dropped first if too long)
  const rationale = [];
  const base = (typeof t.fit_score_base === 'number') ? t.fit_score_base : null;
  if (base !== null && base !== score) rationale.push('score de base ' + base);
  if (t.price_expected) rationale.push('attendu ~CHF ' + t.price_expected + (t.price_n_seg ? ' (' + t.price_n_seg + ' biens comparés)' : ''));
  if (Array.isArray(t.score_adjustments) && t.score_adjustments.length) rationale.push(esc(t.score_adjustments.join(', ')));
  if (rationale.length) detail.push('⚖️ ' + rationale.join(' · '));
} else if (l.agency) {
  detail.push('\u{1F3E2} ' + esc(l.agency) + (l.agency_reputation ? ' — ' + esc(l.agency_reputation) : ''));
}

const footer = l.url
  ? '\u{1F517} <a href="' + l.url + '">Voir l’annonce</a> · via ' + esc(l.source)
  : 'via ' + esc(l.source);

// ---- assemble with a hard 1024-char caption guard (sendPhoto limit) ----
// Detail lines are whole (never split mid-tag), so popping the lowest-priority
// line keeps the HTML valid while staying under the cap.
const MAX = 1000; // headroom under Telegram's 1024 caption limit
const assemble = (det) => {
  let body = core.join('\n');
  if (det.length) body += '\n<blockquote expandable>' + det.join('\n') + '</blockquote>';
  return body + '\n' + footer;
};
let text = assemble(detail);
while (text.length > MAX && detail.length) { detail.pop(); text = assemble(detail); }

const photo = (Array.isArray(l.images) && l.images.length) ? l.images[0] : null;
return [{ json: { text, photo } }];

// crossKey(listing) — coarse "blocking" fingerprint of a physical apartment, stable across
// portals despite address-formatting noise. It intentionally does NOT include rent: units in
// the same building share a key, and the cross-dup QUERY separates them with a rent tolerance
// (same building, different rent = different unit; same building, ~same rent = same flat on
// two portals). Returns null when there isn't enough to match on.
function crossKey(l) {
  const strip = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  const commune = strip(l.commune).replace(/[^a-z0-9]+/g, '');
  const rooms = (l.rooms != null && !isNaN(l.rooms)) ? Number(l.rooms).toFixed(1) : null;
  if (!commune || !rooms) return null;

  const STREET = new Set(['rue','route','rte','avenue','av','ave','chemin','ch','impasse','imp',
    'place','pl','boulevard','bd','allee','quai','sentier','ruelle','esplanade','promenade',
    'clos','montee','passage','vieux','vieille','grand','grande']);
  const ART = new Set(['du','de','des','la','le','les','l','d','en','aux','au','sur','a']);
  const communeSet = new Set(strip(l.commune).split(/[^a-z0-9]+/).filter(Boolean));

  let addr = strip(l.address_raw).replace(/\b\d{4}\b/g, ' '); // drop NPA
  const tokens = addr.split(/[^a-z0-9]+/).filter(Boolean);
  const nums = tokens.filter(t => /^\d{1,3}$/.test(t));
  const number = nums.length ? nums[nums.length - 1] : null; // house number = last small number
  const streetToken = tokens.find(t =>
    /^[a-z]/.test(t) && !STREET.has(t) && !ART.has(t) && !communeSet.has(t)) || null;

  const rent = l.rent_gross ?? l.rent_net;
  const m2 = (l.m2 != null && !isNaN(l.m2)) ? Math.round(Number(l.m2)) : null;
  let geo = null;
  if (streetToken) geo = number ? streetToken + '-n' + number : streetToken;
  else if (m2) geo = 'm' + m2;              // sparse SMG alerts: no street/rent but have m²
  else if (rent != null) geo = 'r' + (Math.round(rent / 100) * 100);
  if (!geo) return null;
  return commune + '|' + rooms + '|' + geo;
}

const l = $json;
return [{ json: { ...l, cross_key: crossKey(l) } }];

const listing = $('Enrich').item.json;
const canon = ($json && $json.id) ? $json : null;
return [{ json: { ...listing, _dup_of: canon ? canon.id : null, _canonical: canon } }];
